{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "full",
      "summary_quote": "It applies when an order of protection is issued under the state's order-of-protection law to protect one public school student from another student enrolled in the same school. In that case, the school principal must remove the student named as the respondent (the person the order is against) from any classroom, school-sponsored event, or activity shared with the student named as the petitioner (the person the order protects).",
      "rationale": "Conveys the qualifying protection order, same-public-school condition, principal's duty, and removal from shared classrooms and school-sponsored events or activities."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "The school or school district must give the removed respondent alternative instruction for any class or course from which that student is removed.",
      "rationale": "Identifies the responsible school or district and requires alternative instruction for every class or course from which the respondent is removed."
    },
    {
      "proposition_id": "P3",
      "status": "full",
      "summary_quote": "The removal is required only for as long as the order of protection is in effect.",
      "rationale": "Expressly limits required removal to the period the protection order remains in effect."
    },
    {
      "proposition_id": "P4",
      "status": "full",
      "summary_quote": "The bill would take effect when it becomes law and would apply to orders of protection entered on or after that date.",
      "rationale": "Includes both the effective date and the limitation to orders entered on or after that date."
    }
  ]
}
